import { createTopologyPageController } from "./pageTopologyController.ts";
import {
  createSceneNavigationController,
  type SceneNavigationController,
  type SceneNavigationControllerOptions,
} from "./sceneNavigationController.ts";
import {
  resolveTopologySelectionKind,
  type TopologyNavigationKind,
  type TopologySelectionCause,
} from "./selectionContract.ts";
import {
  resolveRelationshipContext,
  type ContextRelationship,
  type RelationshipContext,
} from "./relationshipContext.ts";

export interface TopologyContentSelection {
  entityId: string;
  previousId: string | null;
  kind: TopologyNavigationKind;
  cause: TopologySelectionCause;
  relationshipContext: RelationshipContext;
}

export interface TopologyContentPageControllerOptions {
  scene: HTMLElement;
  initialId: string;
  relationships?: ContextRelationship[];
  navigation: Omit<
    SceneNavigationControllerOptions,
    "scene" | "selectedId" | "onMiniMapNodeSelect"
  >;
  onSelection: (selection: TopologyContentSelection) => void;
  onNavigationStateChange?: (active: boolean) => void;
}

export interface TopologyContentPageController {
  navigation: SceneNavigationController;
  getSelectedId(): string;
  select(entityId: string, kind?: TopologyNavigationKind): void;
  destroy(): void;
}

export function createTopologyContentPageController({
  scene,
  initialId,
  relationships = [],
  navigation: navigationOptions,
  onSelection,
  onNavigationStateChange,
}: TopologyContentPageControllerOptions): TopologyContentPageController {
  let activeId = "";

  function applySelection(
    entityId: string,
    kind: TopologyNavigationKind,
    cause: TopologySelectionCause,
  ) {
    if (!entityId) return;
    const previousId = activeId || null;
    const isSettledNavigation = entityId === activeId && cause === "navigation";
    const relationshipContext = resolveRelationshipContext(entityId, relationships);
    activeId = entityId;
    navigation.select(entityId);
    navigation.syncRelationshipContext(relationshipContext);
    if (cause !== "programmatic") {
      navigation.ensureVisible(entityId, true);
    }
    scene.dispatchEvent(new CustomEvent("topology-relationship-context", {
      detail: relationshipContext,
    }));
    if (!isSettledNavigation) {
      onSelection({ entityId, previousId, kind, cause, relationshipContext });
    }
  }

  function select(entityId: string, kind: TopologyNavigationKind = "select") {
    if (!entityId) return;
    const sourceId = activeId || null;
    applySelection(entityId, kind, "selection");
    page.navigate({ fromId: sourceId, toId: entityId, kind });
  }

  const navigation = createSceneNavigationController({
    ...navigationOptions,
    scene,
    selectedId: initialId,
    onMiniMapNodeSelect(entityId) {
      select(entityId, "select");
    },
  });

  const page = createTopologyPageController({
    scene,
    onNodeSelected(detail) {
      applySelection(
        detail.nodeId,
        resolveTopologySelectionKind(detail),
        detail.cause ?? "pointer",
      );
    },
    onNavigationStateChange,
  });

  applySelection(initialId, "focus", "programmatic");

  return {
    navigation,
    getSelectedId: () => activeId,
    select,
    destroy() {
      page.destroy();
      navigation.destroy();
    },
  };
}
